import re,glob,sys,os
U=["centerpoint","northern indiana public service","nipsco","citizens gas","citizens energy","vectren","indiana american water","ohio valley gas","american electric power","duke energy","community natural gas","midwest natural gas","frontier communications"]
lab=re.compile(r'^(Respondent|Other Party|Case Number|Date\s\w+\s(Advisory|Dam)|Damage Location)[^:]*:')
res={}
for f in sorted(glob.glob('ord_*.txt')):
    yr=2000+int(re.search(r'(\d\d)\.txt',f).group(1))
    if yr not in(2021,2025): continue
    for pg in re.split(r'=== page \d+\n',open(f).read())[1:]:
        if 'Respondent' not in pg: continue
        reg=pg[pg.index('Respondent'):]
        reg=reg[:reg.index('The IURC')] if 'The IURC' in reg else reg
        L=[l.strip() for l in reg.split('\n') if l.strip()]
        inl={};vals=[]
        for l in L:
            m=lab.match(l)
            if m: inl[m.group(1)]=l[m.end():].strip()
            else: vals.append(l)
        r=inl.get('Respondent','')
        cn=inl.get('Case Number','')
        if not r:
            ci=next((i for i,v in enumerate(vals) if re.fullmatch(r'\d{4,6}',v)),None)
            if ci is None or ci<2:
                if vals: print('SKIP?',f,vals[:6])
                continue
            r=vals[ci-2]; 
            if ci>2 : print('NOTE',f,vals[:ci+1])
        pm=re.search(r'civil penalty:\s*(.*?)(?:Abstentions|$)',pg,re.S) or re.search(r'recommends the following penalty:\s*(.*?)(?:Abstentions|$)',pg,re.S)
        t=pm.group(1) if pm else ''
        if 'Civil penalty of' in t and ('□' in t or '~' in t):
            print('CHECKBOX',f,r)
            chk=[l for l in t.split('\n') if re.match(r'\s*[~X☒✓xK]',l) ]
            t='\n'.join(chk)
        a=re.search(r'\$+\s*(\d[\d, ]*(?:\.\d+)?)',t)
        amt=0
        if a: amt=float(re.sub(r'[ ,]','',a.group(1)).rstrip('.') )
        u=any(r.lower().lstrip().startswith(x) for x in U)
        print(yr,f,'|',r,'|',' '.join(t.split())[:80],'|',amt,u)
        res.setdefault(yr,[]).append((u,amt))
for y,v in res.items():
    n=[a for u,a in v if not u]; print('RES',y,len(v),len(n),sum(n),sum(n)/len(n))
